190	// Walks every condition node (including untaken branches) and turns it into a
191	// pre-validated, pre-resolved structure. Any malformed condition throws with a
192	// node id and a `$`-style child position, before the workflow can execute.
193	function compileCondition(condition, nodes, nodeId, position = '$', depth = 1) {
194	  if (depth > MAX_CONDITION_DEPTH) {
195	    throw new Error(`condition node ${nodeId} at ${position}: conditions must not be nested deeper than ${MAX_CONDITION_DEPTH} levels`);
196	  }
197	  if (!isUsableObject(condition)) {
198	    throw new Error(`condition node ${nodeId} at ${position}: condition must be an object`);
199	  }
200	
201	  const comboKeys = [];
202	  if (Object.hasOwn(condition, 'all')) comboKeys.push('all');
203	  if (Object.hasOwn(condition, 'any')) comboKeys.push('any');
204	  if (Object.hasOwn(condition, 'not')) comboKeys.push('not');
205	  if (comboKeys.length > 1) {
206	    throw new Error(`condition node ${nodeId} at ${position}: condition must use only one of all, any or not`);
207	  }
208	
209	  const comparisonKeys = ['field', 'outputField', 'operator', 'value', 'valueField', 'valueOutputField'];
210	  const presentComparisonKeys = comparisonKeys.filter(key => Object.hasOwn(condition, key));
211	
212	  if (comboKeys.length === 1) {
213	    if (presentComparisonKeys.length > 0) {
214	      throw new Error(`condition node ${nodeId} at ${position}: ${comboKeys[0]} condition must not mix in field, outputField, operator, value, valueField or valueOutputField`);
215	    }
216	    const key = comboKeys[0];
217	    if (key === 'not') {
218	      return { kind: 'not', child: compileCondition(condition.not, nodes, nodeId, `${position}.not`, depth + 1) };
219	    }
220	    if (!Array.isArray(condition[key])) {
221	      throw new Error(`condition node ${nodeId} at ${position}: ${key} must be an array of conditions`);
222	    }
223	    if (condition[key].length === 0) {
224	      throw new Error(`condition node ${nodeId} at ${position}: ${key} must not be empty`);
225	    }
226	    return {
227	      kind: key,
228	      children: condition[key].map((child, index) =>
229	        compileCondition(child, nodes, nodeId, `${position}.${key}[${index}]`, depth + 1)),
230	    };
231	  }
232	
233	  const where = `condition node ${nodeId} at ${position}`;
234	  const hasField = Object.hasOwn(condition, 'field');
235	  const hasOutputField = Object.hasOwn(condition, 'outputField');
236	  if ((!hasField && !hasOutputField) || !Object.hasOwn(condition, 'operator')) {
237	    throw new Error(`${where}: condition must be a comparison (field and operator) or a compound (all, any or not)`);
238	  }
239	  if (hasField && hasOutputField) {
240	    throw new Error(`${where}: condition must specify exactly one of field or outputField`);
241	  }
242	
243	  if (!['eq', 'gte', 'lte', 'exists'].includes(condition.operator)) {
244	    throw new Error(`${where}: unknown condition operator: ${condition.operator}`);
245	  }
246	
247	  let left;
248	  if (hasField) {
249	    left = { kind: 'input', label: 'field', segments: parsePathSegments(condition.field, `${where} field`) };
250	  } else {
251	    left = {
252	      kind: 'output', label: 'outputField',
253	      ref: compileOutputReference(condition.outputField, nodes, `${where} outputField`),
254	    };
255	  }
256	
257	  if (condition.operator === 'exists') {
258	    const unexpected = presentComparisonKeys.filter(key =>
259	      key === 'value' || key === 'valueField' || key === 'valueOutputField');
260	    if (unexpected.length > 0) {
261	      throw new Error(`${where}: exists only takes field and operator (outputField may name the left side)`);
262	    }
263	    return { kind: 'comparison', operator: 'exists', left };
264	  }
265	
266	  const hasValue = Object.hasOwn(condition, 'value');
267	  const hasValueField = Object.hasOwn(condition, 'valueField');
268	  const hasValueOutput = Object.hasOwn(condition, 'valueOutputField');
269	  const rightCount = [hasValue, hasValueField, hasValueOutput].filter(Boolean).length;
270	  if (rightCount !== 1) {
271	    throw new Error(`${where}: condition must specify exactly one of value or valueField (or valueOutputField)`);
272	  }
273	
274	  let right;
275	  if (hasValue) {
276	    if (!isComparableConstant(condition.value)) {
277	      throw new Error(`${where}: value must be a string, finite number, boolean or null`);
278	    }
279	    right = { kind: 'constant', label: 'value', value: condition.value };
280	    if (condition.operator !== 'eq') {
281	      const numericValue = toComparableNumber(condition.value);
282	      if (numericValue === null) {
