467	// Resolves the explicit dependencies of a node. Dependencies only gate when a
468	// node may run; they never activate it. A missing dependsOn means no
469	// dependencies, and the entry node must not declare any.
470	function normalizeDependencies(node, nodes, entryId) {
471	  if (!Object.hasOwn(node, 'dependsOn') || node.dependsOn === undefined) return [];
472	  if (!Array.isArray(node.dependsOn)) {
473	    throw new Error(`node ${node.id}: dependsOn must be an array`);
474	  }
475	  const seen = new Set();
476	  for (const dependency of node.dependsOn) {
477	    if (typeof dependency !== 'string') {
478	      throw new Error(`node ${node.id}: dependsOn entries must be node id strings`);
479	    }
480	    if (seen.has(dependency)) {
481	      throw new Error(`node ${node.id}: duplicate dependency ${dependency}`);
482	    }
483	    seen.add(dependency);
484	    if (!nodes.has(dependency)) {
485	      throw new Error(`node ${node.id} depends on an unknown node`);
486	    }
487	    if (dependency === node.id) {
488	      throw new Error(`node ${node.id} must not depend on itself`);
489	    }
490	  }
491	  const dependencies = [...seen];
492	  if (node.id === entryId && dependencies.length > 0) {
493	    throw new Error(`entry node ${node.id} must not declare dependencies`);
494	  }
495	  return dependencies;
496	}
