1	import test from 'node:test';
2	import assert from 'node:assert/strict';
3	import { executeWorkflow, executeWorkflowAsync } from '../src/engine.js';
4	
5	const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
6	
7	// trigger -> work (business) -> done
8	function linearWorkflow(actionProps = {}) {
9	  return {
10	    id: 'cancellable',
11	    entry: 'start',
12	    nodes: [
13	      { id: 'start', type: 'trigger', next: 'work' },
14	      { id: 'work', type: 'action', ...actionProps, next: 'done' },
15	      { id: 'done', type: 'end', result: 'finished' },
16	    ],
17	  };
18	}
19	
20	test('omitted, undefined or signal-less options keep the existing behavior', async () => {
21	  const workflow = linearWorkflow({ operation: 'echo' });
22	  const operations = { echo: () => 'ok' };
23	  for (const options of [undefined, {}, { signal: undefined }]) {
24	    const execution = options === undefined
25	      ? await executeWorkflowAsync(workflow, {}, operations)
26	      : await executeWorkflowAsync(workflow, {}, operations, options);
27	    assert.equal(execution.status, 'completed');
28	    assert.equal(execution.result, 'finished');
29	    assert.equal(execution.context.output.work, 'ok');
30	    assert.equal(execution.compensationStatus, 'not_needed');
31	  }
32	});
33	
34	test('options of any other type are rejected before any node executes', async () => {
35	  const workflow = linearWorkflow({ operation: 'echo' });
36	  let called = 0;
37	  const operations = { echo: () => { called += 1; return 'ok'; } };
