    () => new Int16Array(new SharedArrayBuffer(4)),
    () => new Uint16Array(new SharedArrayBuffer(4)),
    () => new Int32Array(new SharedArrayBuffer(8)),
    () => new Uint32Array(new SharedArrayBuffer(8)),
